/* clean-artifacts.js -- MdToHtml Pro one-shot build-artifact cleaner.
 *
 * Removes every REGENERABLE build/test artifact so generated files never
 * accumulate in multiple folders. Canonical output locations of this repo:
 *   - Web build      -> .next/    (regenerated by `npm run build`)
 *   - Desktop bundle -> release/  (regenerated by electron-builder)
 *
 * NEVER touches: src/, docs/, data/ (document library), output/ (exported
 * results), posts/, .trash/ (app recycle bin) or any configuration.
 *
 * Usage: node scripts/clean-artifacts.js   (run from MdToHtml/)
 */
const fs = require('fs');
const path = require('path');

const BASE = path.resolve(__dirname, '..');

const TARGETS = [
  '.next',
  'dist',
  'dist_build',
  'dist_build_v2',
  'release',
  'release_v2',
  'out',
  'coverage',
  'temp',
  '.swc',
  'test-results',
  'playwright-report',
];

function dirSize(p) {
  if (!fs.existsSync(p)) return 0;
  let total = 0;
  (function walk(d) {
    let entries;
    try { entries = fs.readdirSync(d, { withFileTypes: true }); } catch (e) { return; }
    for (const e of entries) {
      const fp = path.join(d, e.name);
      try {
        if (e.isDirectory()) walk(fp);
        else total += fs.statSync(fp).size;
      } catch (e) { /* locked file -> skip */ }
    }
  })(p);
  return total;
}

let freed = 0;
for (const t of TARGETS) {
  const p = path.join(BASE, t);
  if (!fs.existsSync(p)) {
    console.log('[skip]    ' + t + ' (not present)');
    continue;
  }
  const before = dirSize(p);
  fs.rmSync(p, { recursive: true, force: true });
  const removed = !fs.existsSync(p);
  if (removed) freed += before;
  console.log('[' + (removed ? 'deleted' : 'LOCKED ') + '] ' + t + '  (' + (before / 1048576).toFixed(1) + ' MB)');
}
console.log('');
console.log('Total freed: ' + (freed / 1048576).toFixed(1) + ' MB');
console.log('Note: .next/ and release/ are regenerated on demand (npm run build / electron-builder).');
